SELECT
tfr.*,
pt.name AS toilet_name,
sf.name AS facility_name,
u1.user_name AS report_name,
u2.user_name AS repair_name
FROM public_toilet_facility_repair tfr
LEFT JOIN public_toilet pt ON tfr.toilet_id = pt.toilet_id AND pt.deleted = 0
LEFT JOIN sys_facility sf ON tfr.facility_id = sf.sys_facility_id AND sf.deleted = 0
LEFT JOIN sys_user u1 ON tfr.report_by = u1.user_id AND u1.deleted = 0
LEFT JOIN sys_user u2 ON tfr.repair_by = u2.user_id AND u2.deleted = 0
WHERE tfr.deleted = 0



    AND tfr.repair_id = #{reqVO.repairId}




    AND tfr.toilet_id = #{reqVO.toiletId}




    AND pt.name LIKE CONCAT('%', #{reqVO.toiletName}, '%')




    AND tfr.facility_id = #{reqVO.facilityId}




    AND sf.name LIKE CONCAT('%', #{reqVO.facilityName}, '%')




    AND tfr.damage_desc LIKE CONCAT('%', #{reqVO.damageDesc}, '%')




    AND tfr.report_by = #{reqVO.reportBy}




    AND u1.user_name LIKE CONCAT('%', #{reqVO.reportName}, '%')




    AND tfr.report_time BETWEEN #{reqVO.reportTime[0]} AND #{reqVO.reportTime[1]}




    AND tfr.repair_by = #{reqVO.repairBy}




    AND u2.user_name LIKE CONCAT('%', #{reqVO.repairName}, '%')




    AND tfr.repair_status = #{reqVO.repairStatus}




    AND tfr.expected_complete_time BETWEEN #{reqVO.expectedCompleteTime[0]} AND #{reqVO.expectedCompleteTime[1]}




    AND tfr.actual_complete_time BETWEEN #{reqVO.actualCompleteTime[0]} AND #{reqVO.actualCompleteTime[1]}




    AND tfr.accept_result = #{reqVO.acceptResult}




    AND tfr.accept_opinion LIKE CONCAT('%', #{reqVO.acceptOpinion}, '%')




    AND tfr.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}




    AND tfr.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}


ORDER BY tfr.id DESC
LIMIT #{reqVO.offset}, #{reqVO.pageSize}

SELECT COUNT(*)
FROM public_toilet_facility_repair tfr
LEFT JOIN public_toilet pt ON tfr.toilet_id = pt.toilet_id AND pt.deleted = 0
