    AND u1.user_name LIKE CONCAT('%', #{reqVO.reportName}, '%')




    AND tfr.report_time BETWEEN #{reqVO.reportTime[0]} AND #{reqVO.reportTime[1]}




    AND tfr.repair_by = #{reqVO.repairBy}




    AND u2.user_name LIKE CONCAT('%', #{reqVO.repairName}, '%')




    AND tfr.repair_status = #{reqVO.repairStatus}




    AND tfr.expected_complete_time BETWEEN #{reqVO.expectedCompleteTime[0]} AND #{reqVO.expectedCompleteTime[1]}




